      <dialog ref="detailDialog" class="qj-dialog qj-detail" aria-labelledby="qj-detail-title" @cancel.prevent="closeDetail" @close="stopPlayer"><header><div><span class="qj-eyebrow">QGAUSS / TAKE A CLOSER LOOK</span><h2 id="qj-detail-title">喜欢，<em>值得再靠近一点。</em></h2></div><button type="button" aria-label="关闭 MJ 作品详情" @click="closeDetail">×</button></header><BrandLoader v-if="detailLoading" text="正在展开这份想象…"/><div v-else-if="detailError" class="qj-alert" role="alert">{{ detailError }}</div><template v-else-if="detail"><div class="qj-detail-stage"><video v-if="selectedResult?.kind === 'video' && playback?.videoUrl" ref="player" :src="playback.videoUrl" :poster="imageUrl(selectedResult.posterUrl)" controls playsinline preload="metadata" aria-label="MJ 成片播放器" @error="playbackError = true"></video><img v-else-if="selectedResult?.kind === 'image' && imageUrl(selectedResult.url)" :src="imageUrl(selectedResult.url)" :alt="detail.prompt || detail.kindName"/><div v-else-if="detail.text" class="qj-text-result"><span>WORDS FOR YOUR NEXT IDEA</span><pre>{{ detail.text }}</pre><button type="button" @click="useText(detail.text)">把这些文字带回创作台 ↗</button></div><div v-else class="qj-stage-message"><BrandLoader v-if="mjActive(detail)"/><b>{{ mjStatus(detail.status) }}</b><p>{{ detail.message }}</p></div></div><div v-if="playbackError" class="qj-alert" role="alert">播放地址可能已过期。<button type="button" @click="loadPlayback(detail,selectedIndex,true)">刷新播放地址</button></div><div v-if="detail.results?.length > 1" class="qj-result-tabs"><button v-for="(r,i) in detail.results" :key="r.fileId" type="button" :aria-pressed="selectedIndex === i" @click="selectResult(i)">{{ r.kind === 'video' ? '片段' : '画面' }} {{ i+1 }}</button></div><div class="qj-detail-copy"><div><h3>{{ detail.kindName }}</h3><p>{{ detail.prompt }}</p><div class="qj-detail-tags"><span>{{ detail.presetName }}</span><span v-if="detail.modelLabel">{{ detail.modelLabel }}</span><span v-if="detail.seed !== undefined && detail.seed !== null">种子 {{ detail.seed }}</span></div></div><dl v-if="detail.mine && detail.billing" class="qj-bill"><div><dt>本次预留</dt><dd>{{ detail.billing.reserved }} 次</dd></div><div><dt>完成结算</dt><dd>{{ detail.billing.charged }} 次</dd></div><div><dt>已释放</dt><dd>{{ detail.billing.returned }} 次</dd></div><div v-if="detail.billing.expired"><dt>过期权益</dt><dd>{{ detail.billing.expired }} 次</dd></div></dl></div>
      <section v-if="detail.mine && detail.status === 'SUCCESS' && detail.actions?.length" class="qj-action-deck" aria-label="MJ 原生创作操作"><div v-for="group in mjActionGroups(detail.actions)" :key="group.name"><h3>{{ group.name }}</h3><div><button v-for="a in group.items" :key="a.id" type="button" :disabled="a.supported === false" :title="a.reason || a.label" @click="activateAction(detail,a)"><span>{{ a.label }}</span><small>{{ a.costHint || (a.needsMask ? '涂抹后确认' : a.needsPrompt ? '补充想法' : '确认后开始') }}</small></button></div></div></section>
      <section v-if="detail.mine && detail.status === 'WAITING_INPUT'" class="qj-modal-resume"><h3>再添一点想法，就能继续。</h3><p v-if="pendingModal?.payload.taskId === detail.id">上一份补充回执尚未确认，重试会继续使用同一标识与描述。</p><textarea v-model="modalPrompt" aria-label="补充 MJ 创作描述" rows="3" maxlength="4000" placeholder="描述这次想改变的内容…"></textarea><p>继续沿用本次预留，不重复创建最初的动作。</p><button type="button" class="qj-primary" :disabled="busy.has(detail.id)" @click="resumeModal">确认补充并继续 ↗</button></section>
