<script setup>
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { RouterLink } from 'vue-router';
import { ElMessage } from 'element-plus';
import { api, uploadFile } from '../api/client.js';
import { useAuth } from '../stores/auth.js';
import { createArtworkAssets } from '../lib/artwork-assets.js';
import { mjIntent, mjModalIntent, mjActive, mjStatus, mjKinds, mjRoles, mjPools, mjResultKind, mjActionGroups } from '../lib/midjourney-presentation.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import BrandLoader from '../components/design/BrandLoader.vue';
import ImageMaskEditor from '../components/design/ImageMaskEditor.vue';
import '../components/design/midjourney-workspace.css';

const auth = useAuth(), owner = auth.user?.id, intentStore = mjIntent(owner), modalStore = mjModalIntent(owner);
const pendingModal = ref(modalStore.read());
let alive = true, timer, opener, detailRevision = 0;
const current = () => alive && auth.isLoggedIn && auth.user?.id === owner;
const controllers = new Map(), localUrls = new Map(), assets = createArtworkAssets(current);
function scope(key) { controllers.get(key)?.abort(); const c = new AbortController(); controllers.set(key,c); return { signal:c.signal, current:() => current() && !c.signal.aborted && controllers.get(key) === c }; }
const presets = ref([]), optionsLoaded = ref(false), optionsError = ref('');
const form = reactive({ presetId:'', kind:'imagine', prompt:'', model:'mj', version:'7', ratio:'1:1', quality:1, hd:false, raw:false, stylize:100, chaos:0, seed:'', negativePrompt:'', imageWeight:1, characterWeight:100, styleWeight:100, dimensions:'SQUARE', motion:'low', videoType:'vid_1.1_i2v_480', batchSize:4, loop:false, zoom:1.5, remix:false, strong:false });
const selected = computed(() => presets.value.find(p => p.id === form.presetId));
const kinds = mjKinds, tabs = [{key:'mine',name:'我的想象'},{key:'square',name:'灵感展厅'},{key:'trash',name:'回收站'}];
const versions = computed(() => selected.value?.features.versions?.[form.model] || ['7']);
const qualityChoices = computed(() => selected.value?.features.qualities?.[form.version] || [1]);
const sourceAction = ref(null), references = ref([]), uploadRole = ref('image'), fileInput = ref(null), uploading = ref(false), maskEditor = ref(null), mask = ref(null);
const referenceRoles = computed(() => form.kind === 'imagine' ? selected.value?.features.roles?.[form.version] || ['image'] : form.kind === 'blend' || form.kind === 'describe' ? ['image'] : form.kind === 'swap' ? ['faceSource','faceTarget'] : form.kind === 'video' ? form.loop ? ['first'] : ['first','last'] : []);
const referenceError = computed(() => !sourceAction.value && references.value.some(r => !referenceRoles.value.includes(r.role)) ? '当前方式或版本不接收这类素材，请移除或切回原版本。' : '');
const activeWeights = computed(() => [{role:'image',key:'imageWeight',label:'画面参考权重',min:0,max:form.version === '5.2'?2:3,step:.1},{role:'character',key:'characterWeight',label:'主体参考权重',min:0,max:form.version === '7'?1000:100,step:1},{role:'style',key:'styleWeight',label:'风格参考权重',min:0,max:1000,step:1}].filter(w => references.value.some(r => r.role === w.role)));
const sourceImage = computed(() => sourceAction.value?.task.results?.find(r => r.kind === 'image')?.url ? imageUrl(sourceAction.value.task.results.find(r => r.kind === 'image').url) : '');
const showPrompt = computed(() => !['blend','describe','swap'].includes(form.kind));
const tasks = ref([]), total = ref(0), loading = ref(false), listError = ref(''), page = ref(1), pageSize = 12, tab = ref('mine'), busy = reactive(new Set());
const activeCount = computed(() => tasks.value.filter(mjActive).length);
const estimate = computed(() => { const key = sourceAction.value?.action.priceKey || form.kind, price = selected.value?.prices?.[key]; return price === undefined ? '次数会在开始前再次确认' : '基础 ' + price + ' ' + (mjPools[selected.value?.pool] || '次数') + ' · 按版本与参数核对后确认'; });
const quoting = ref(false), submitting = ref(false), recovering = ref(false), pendingIntent = ref(intentStore.read()), quote = ref(null), quotePayload = ref(null), confirmDialog = ref(null);
const detailDialog = ref(null), detail = ref(null), detailLoading = ref(false), detailError = ref(''), selectedIndex = ref(0), player = ref(null), playback = ref(null), playbackError = ref(false), downloading = ref(false), publishConfirm = ref(false), deleteConfirm = ref(false), modalPrompt = ref('');
const selectedResult = computed(() => detail.value?.results?.[selectedIndex.value]);
const ideas = [{ title:'玻璃里的春天',icon:'✦',note:'透明材质 · 柔光',prompt:'一座盛开在透明玻璃球里的微型花园，淡紫与青柠，柔和晨光，细腻材质，带一点童话般的立体感。' },{ title:'会发光的小城市',icon:'◌',note:'夜色 · 微缩世界',prompt:'夜色里漂浮的小小城市，窗户透出暖光，青紫色天空，温柔光晕，精细的微缩建筑，电影感。' },{ title:'把快乐捏成形状',icon:'◒',note:'软胶 · 活泼撞色',prompt:'青柠和珊瑚色的软胶雕塑组合，像一个快乐的感叹号，奶油背景，圆润材质，俏皮、简洁、有活力。' }];
const imageUrl = path => assets.urls.get(path) || '';
const referenceUrl = r => localUrls.get(r.id) || imageUrl('/api/upload/' + r.id + '/raw');
const imageFailed = task => mediaPaths([task]).some(path => assets.errors.has(path));
function retryImages(task) { for (const path of mediaPaths([task])) void assets.load({url:path},true); }
const cover = task => imageUrl(task.results?.find(r => r.kind === 'image' || r.posterUrl)?.posterUrl || task.results?.find(r => r.kind === 'image')?.url);
const date = value => value ? new Date(value).toLocaleString('zh-CN',{hour12:false}) : '';
function mediaPaths(rows) { return rows.flatMap(t => (t.results || []).flatMap(r => r.kind === 'image' ? [r.url] : r.posterUrl ? [r.posterUrl] : [])); }
function retainAssets() { const paths = new Set([...mediaPaths(tab.value === 'trash' ? [] : tasks.value), ...mediaPaths(detail.value ? [detail.value] : []), ...mediaPaths(sourceAction.value ? [sourceAction.value.task] : []), ...references.value.filter(r => !localUrls.has(r.id)).map(r => '/api/upload/' + r.id + '/raw')]); assets.retain(paths); for (const path of paths) void assets.load({url:path}); }
async function loadOptions() { const req = scope('options'); optionsError.value = ''; try { const data = await api.get('/mj/options',{signal:req.signal}); if (!req.current()) return; presets.value = data.presets || []; optionsLoaded.value = true; if (!selected.value) form.presetId = presets.value.find(p => p.ready)?.id || presets.value[0]?.id || ''; } catch(e) { if (req.current()) optionsError.value = e.message || '创作连接暂未打开'; } }
async function loadTasks() { const req = scope('list'), kind = tab.value; loading.value = true; listError.value = ''; try { const data = await api.get('/mj/' + (kind === 'mine' ? 'tasks' : kind) + '?page=' + page.value + '&pageSize=' + pageSize,{signal:req.signal}); if (!req.current()) return; tasks.value = data.items || []; total.value = data.total || 0; retainAssets(); if (detail.value && mjActive(detail.value)) await refreshDetail(detail.value.id,detailRevision); } catch(e) { if (req.current()) listError.value = e.message || '作品暂未展开'; } finally { if (req.current()) loading.value = false; } }
function chooseKind(kind) { form.kind = kind; mask.value = null; }
function removeReference(index) { const [r] = references.value.splice(index,1); if (r && localUrls.has(r.id)) { URL.revokeObjectURL(localUrls.get(r.id)); localUrls.delete(r.id); } retainAssets(); }
async function uploadReferences(event) { const files = [...event.target.files || []]; event.target.value = ''; if (!files.length || uploading.value) return; const max = form.kind === 'blend' ? selected.value?.features.blendLimit || 5 : form.kind === 'describe' ? 1 : ['swap','video'].includes(form.kind) ? 2 : 8; if (references.value.length + files.length > max) return ElMessage.warning('当前方式最多 ' + max + ' 张参考图'); if (files.some(f => !/^image\/(png|jpeg|webp|gif)$/.test(f.type) || f.size > 10*1024*1024)) return ElMessage.warning('请选择不超过 10 MB 的静态图片'); const req = scope('upload'), role = uploadRole.value; uploading.value = true; try { for (const file of files) { const r = await uploadFile(file,{signal:req.signal}); if (!req.current()) return; references.value.push({id:r.id,role}); localUrls.set(r.id,URL.createObjectURL(file)); } } catch(e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) uploading.value = false; } }
async function saveMask(data) { const source = sourceAction.value; if (!source || uploading.value) return; const req = scope('mask'); uploading.value = true; try { const saved = await uploadFile(new File([data.blob],'QGauss-region.png',{type:'image/png'}),{signal:req.signal}); if (req.current() && sourceAction.value === source) { mask.value = {id:saved.id,strokes:data.strokes}; ElMessage.success('选区已保存，确认改动后再开始。'); } } catch(e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) uploading.value = false; } }
function payload() { if (!selected.value?.ready) throw Error('请先选择已就绪的创作连接'); if (referenceError.value) throw Error(referenceError.value); const base = { presetId:form.presetId,kind:form.kind,prompt:form.prompt.trim() }; if (['imagine','shorten'].includes(form.kind) && !base.prompt) throw Error('先写下你想表达的画面'); if (form.kind === 'action') { if (!sourceAction.value) throw Error('先选择本人作品的操作'); if (sourceAction.value.action.needsMask && !mask.value?.id) throw Error('先打开画布并保存想改变的区域'); return {...base,sourceTaskId:sourceAction.value.task.id,actionId:sourceAction.value.action.id,...(sourceAction.value.action.customZoom?{zoom:form.zoom}:{}),...(mask.value?.id?{maskId:mask.value.id}:{}),remix:form.remix,strong:form.strong}; } if (form.kind === 'shorten') return base; if (form.kind === 'video') return {...base, motion:form.motion,videoType:form.videoType,batchSize:form.batchSize,loop:form.loop,...(sourceAction.value?{sourceTaskId:sourceAction.value.task.id,sourceIndex:sourceAction.value.action.index || 0}:{references:references.value.map(r=>({id:r.id,role:r.role}))})}; if (['blend','describe','swap'].includes(form.kind)) return {...base,references:references.value.map(r=>({id:r.id,role:r.role})),...(form.kind === 'blend'?{dimensions:form.dimensions}:{})}; if (form.seed !== '' && (!Number.isInteger(Number(form.seed)) || Number(form.seed)<0 || Number(form.seed)>4294967295)) throw Error('随机种子需要是有效的非负整数'); return {...base,model:form.model,version:form.version,ratio:form.ratio,quality:form.quality,hd:form.hd,raw:form.raw,stylize:form.stylize,chaos:form.chaos,negativePrompt:form.negativePrompt, imageWeight:form.imageWeight, characterWeight:form.characterWeight, styleWeight:form.styleWeight,...(form.seed === ''?{}:{seed:Number(form.seed)}),references:references.value.map(r=>({id:r.id,role:r.role}))}; }
async function prepareQuote() { if (quoting.value || submitting.value) return; if (pendingIntent.value) return ElMessage.warning('请先找回上一份提交的回执'); let body; try { body = payload(); } catch(e) { return ElMessage.warning(e.message); } const req = scope('quote'); quoting.value = true; try { const data = await api.post('/mj/quote',body,{signal:req.signal}); if (req.current()) { quote.value = data; quotePayload.value = body; confirmDialog.value.showModal(); } } catch(e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) quoting.value = false; } }
function closeConfirm() { if (!submitting.value) confirmDialog.value?.close(); }
async function confirmCreate() { if (submitting.value || !quote.value || !quotePayload.value) return; const intent = {requestKey:pendingIntent.value?.requestKey || crypto.randomUUID(),payload:quotePayload.value,quoteRevision:quote.value.revision}; pendingIntent.value = intent; intentStore.save(intent); const req = scope('submit'); submitting.value = true; try { const task = await api.post('/mj/tasks',{...intent.payload,requestKey:intent.requestKey,quoteRevision:intent.quoteRevision},{signal:req.signal}); if (req.current()) await accepted(task); } catch(e) { if (!req.current()) return; if ([400,402,409,429].includes(e.status)) { intentStore.clear(); pendingIntent.value = null; ElMessage.error(e.message); if (e.status === 409) await loadOptions(); } else { try { const task = await api.get('/mj/tasks/by-request/' + intent.requestKey,{signal:req.signal}); if (req.current()) await accepted(task); } catch { if (req.current()) ElMessage.warning('提交结果尚未确认，请先找回原回执，避免重复开始。'); } } } finally { if (req.current()) { submitting.value = false; confirmDialog.value?.close(); } } }
async function accepted(task) { intentStore.clear(); pendingIntent.value = null; page.value = 1; tab.value = 'mine'; ElMessage.success('灵感已经出发，稍后回来看看。'); await loadTasks(); }
async function recoverIntent() { if (!pendingIntent.value || recovering.value) return; const req = scope('recover'); recovering.value = true; try { const task = await api.get('/mj/tasks/by-request/' + pendingIntent.value.requestKey,{signal:req.signal}); if (req.current()) await accepted(task); } catch(e) { if (req.current()) ElMessage.warning(e.status === 404?'暂未找到原提交，可再次确认同一意图。':'暂时无法找回，请稍后重试。'); } finally { if (req.current()) recovering.value = false; } }
async function retryIntent() { if (!pendingIntent.value || recovering.value) return; const req = scope('retry'); recovering.value = true; try { const data = await api.post('/mj/quote',pendingIntent.value.payload,{signal:req.signal}); if (req.current()) { quote.value = data; quotePayload.value = pendingIntent.value.payload; confirmDialog.value.showModal(); } } catch(e) { if (req.current()) ElMessage.error(e.message); } finally { if (req.current()) recovering.value = false; } }
async function refreshDetail(id,revision) { const req = scope('detail'); try { const row = await api.get('/mj/tasks/' + id,{signal:req.signal}); if (!req.current() || detailRevision !== revision) return; detail.value = row; if (pendingModal.value?.payload.taskId === row.id && row.modalReceipt?.requestKey && (row.modalReceipt.requestKey === pendingModal.value.requestKey || row.status !== 'WAITING_INPUT')) { pendingModal.value = null; modalStore.clear(); } if (row.status === 'WAITING_INPUT' && pendingModal.value?.payload.taskId === row.id) modalPrompt.value = pendingModal.value.payload.prompt; retainAssets(); if (row.results?.[selectedIndex.value]?.kind === 'video') await loadPlayback(row,selectedIndex.value); } catch(e) { if (req.current() && detailRevision === revision) detailError.value = e.message; } }
async function openDetail(task) { opener = document.activeElement; detailLoading.value = true; detail.value = null; detailError.value = ''; selectedIndex.value = 0; playback.value = null; playbackError.value = false; publishConfirm.value = deleteConfirm.value = false; modalPrompt.value = ''; detailDialog.value.showModal(); const revision = ++detailRevision; await refreshDetail(task.id,revision); if (current() && detailRevision === revision) detailLoading.value = false; }
function stopPlayer() { if (player.value) { player.value.pause(); player.value.removeAttribute('src'); player.value.load(); } }
function closeDetail() { ++detailRevision; controllers.get('detail')?.abort(); controllers.get('playback')?.abort(); stopPlayer(); detailDialog.value?.close(); detail.value = null; playback.value = null; retainAssets(); opener?.focus?.({preventScroll:true}); }
async function selectResult(index) { stopPlayer(); selectedIndex.value = index; playback.value = null; if (detail.value?.results?.[index]?.kind === 'video') await loadPlayback(detail.value,index); }
async function loadPlayback(task,index,force=false) { const req = scope('playback'), revision = detailRevision; playbackError.value = false; try { const value = await api.get('/mj/tasks/' + task.id + '/playback?index=' + index,{signal:req.signal}); if (req.current() && revision === detailRevision && selectedIndex.value === index) playback.value = value; } catch { if (req.current()) playbackError.value = true; } }
function clearSource() { sourceAction.value = null; mask.value = null; form.kind = 'imagine'; retainAssets(); }
function reuse(task) { closeDetail(); sourceAction.value = null; mask.value = null; form.kind = 'imagine'; form.prompt = task.prompt || ''; if (presets.value.some(p => p.id === task.presetId)) form.presetId = task.presetId; for (const key of ['model','version','ratio','quality','hd','raw','stylize','chaos','seed','negativePrompt','imageWeight','characterWeight','styleWeight']) if (task.params?.[key] !== undefined) form[key] = task.params[key]; nextTick(() => { if (current()) document.querySelector('#qj-prompt')?.focus(); }); }
function useText(text) { closeDetail(); clearSource(); form.prompt = text.slice(0,4000); nextTick(() => document.querySelector('#qj-prompt')?.focus()); }
function activateAction(task,action) { if (!task.mine || action.supported === false) return; closeDetail(); sourceAction.value = {task,action}; form.presetId = task.presetId; form.kind = action.virtual && ['video','video_extend'].includes(action.kind)?'video':'action'; form.prompt = action.defaultPrompt || ''; mask.value = null; form.remix = !!action.needsPrompt; form.zoom = 1.5; retainAssets(); nextTick(() => document.querySelector('#qj-prompt')?.focus()); }
async function changeTask(task,key,method,path,body) { if (busy.has(task.id)) return; busy.add(task.id); try { const row = await api[method]('/mj/tasks/' + task.id + path,body); if (!current()) return; if (detail.value?.id === task.id && row?.id) detail.value = row; await loadTasks(); return row; } catch(e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function cancel(task) { const row = await changeTask(task,'cancel','post','/cancel'); if (row && current()) ElMessage.success(row.status === 'SUCCESS'?'作品已完成，原结果与结算已保留。':'已停止等待，未结算预留已处理。'); }
async function restore(task) { if (await changeTask(task,'restore','post','/restore')) ElMessage.success('已恢复到我的想象，仅自己可见。'); }
async function publish() { const row = await changeTask(detail.value,'publish','patch','/publish',{published:!detail.value.published}); if (row) publishConfirm.value = false; }
async function remove() { const row = await changeTask(detail.value,'remove','del',''); if (row) closeDetail(); }
async function getSeed() { const task = detail.value; if (!task || busy.has(task.id)) return; busy.add(task.id); try { const value = await api.post('/mj/tasks/' + task.id + '/seed'); if (current() && detail.value?.id === task.id) detail.value = {...detail.value,seed:value.seed}; } catch(e) { if (current()) ElMessage.error(e.message); } finally { if (current()) busy.delete(task.id); } }
async function resumeModal() { const task = detail.value; if (!task || busy.has(task.id)) return; const prompt = modalPrompt.value.trim(); if (!prompt) return ElMessage.warning('请补充这次想改变的内容'); if (pendingModal.value && (pendingModal.value.payload.taskId !== task.id || pendingModal.value.payload.prompt !== prompt)) return ElMessage.warning('请先刷新原作品，找回上一份补充回执后再修改描述'); const intent = pendingModal.value || {requestKey:crypto.randomUUID(),payload:{taskId:task.id,prompt}}; pendingModal.value = intent; modalStore.save(intent); const row = await changeTask(task,'modal','post','/modal',{requestKey:intent.requestKey,prompt:intent.payload.prompt}); if (row?.modalReceipt?.requestKey === intent.requestKey) { pendingModal.value = null; modalStore.clear(); } }
async function downloadResult() { const result = selectedResult.value, task = detail.value; if (!result || !task || downloading.value) return; downloading.value = true; const revision = detailRevision; try { if (result.kind === 'video') { const value = await api.get('/mj/tasks/' + task.id + '/playback?index=' + selectedIndex.value); if (!current() || revision !== detailRevision) return; const link = document.createElement('a'); link.href = value.downloadUrl; link.download = 'QGauss-film.mp4'; document.body.append(link); link.click(); link.remove(); } else { const item = await assets.load(result,true); if (!item) throw Error('作品图片暂未读取，请稍后重试'); if (!current() || revision !== detailRevision) return; const extension = item.blob.type.includes('jpeg') ? 'jpg' : item.blob.type.includes('webp') ? 'webp' : 'png'; const link = document.createElement('a'); link.href = item.url; link.download = 'QGauss-artwork-' + task.id.slice(-8) + '.' + extension; document.body.append(link); link.click(); link.remove(); } } catch(e) { if (current()) ElMessage.error(e.message); } finally { if (current()) downloading.value = false; } }
function normalize() { if (!selected.value) return; if (!sourceAction.value && !selected.value.features.kinds.includes(form.kind)) form.kind = 'imagine'; if (!versions.value.includes(form.version)) form.version = versions.value[0]; if (!qualityChoices.value.includes(form.quality)) form.quality = qualityChoices.value[0]; if (selected.value.speed === 'relax') form.videoType = 'vid_1.1_i2v_480'; if (!selected.value.features.hdVersions?.includes(form.version)) form.hd = false; form.characterWeight = Math.min(form.characterWeight,form.version === '7'?1000:100); form.imageWeight = Math.min(form.imageWeight,form.version === '5.2'?2:3); if (!referenceRoles.value.includes(uploadRole.value)) uploadRole.value = referenceRoles.value[0] || 'image'; }
watch([selected,()=>form.model,()=>form.version,()=>form.kind,()=>form.loop],normalize); watch(tab,()=>{page.value=1;void loadTasks();});
function dispose() { if (!alive) return; alive = false; clearInterval(timer); for (const c of controllers.values()) c.abort(); stopPlayer(); detailDialog.value?.close(); confirmDialog.value?.close(); for (const url of localUrls.values()) URL.revokeObjectURL(url); localUrls.clear(); assets.close(); }
watch(()=>auth.user?.id,id=>{if(id !== owner){intentStore.clear();modalStore.clear();dispose();}});
onMounted(async()=>{await Promise.all([loadOptions(),loadTasks()]);if(current()){if(pendingIntent.value)void recoverIntent();timer=setInterval(()=>{if(current()&&!loading.value&&(activeCount.value||detail.value&&mjActive(detail.value)))void loadTasks();},3500);}});onUnmounted(dispose);
</script>
